class RangeBIT:
    def __init__(self, n={{n}}):
        self.n = n
        self.b1 = [0]*(n+2)
        self.b2 = [0]*(n+2)
    def _upd(self, b, i, v):
        while i <= self.n:
            b[i] += v
            i += i & -i
    def _qry(self, b, i):
        s = 0
        while i > 0:
            s += b[i]
            i -= i & -i
        return s
    def range_add(self, l, r, v):
        self._upd(self.b1, l, v); self._upd(self.b1, r+1, -v)
        self._upd(self.b2, l, v*(l-1)); self._upd(self.b2, r+1, -v*r)
    def prefix(self, i):
        return self._qry(self.b1, i)*i - self._qry(self.b2, i)
    def range_sum(self, l, r):
        return self.prefix(r) - self.prefix(l-1)
